/// <summary>
/// STEP 3 - Обработать действия стратегий по каждому субсчету
/// </summary>
protected void makeAccountActions(RMarketAccount _account)
{
    RMarketSubAccount subAccount;
    RMarketStrategy strategy;
    RMarketStrategySignal strategySignal;
    RMarketConditionTable condition;
    boolean signal;

    //Loop by Subaccounts of main account
    while select subAccount
        where subAccount.AccountId == _account.AccountId
           && subAccount.Active    == NoYes::Yes
    {
        // Loop actions of related strategy
        while select strategySignal
            where strategySignal.Active    == NoYes::Yes
            join strategy
                where strategy.StrategyId == strategySignal.StrategyId
                   && strategy.StrategyId == subAccount.StrategyId
            //TODO notexists join actionLog
        {
            ttsbegin;

            // calculate signal for strategySignal
            signal = strategySignal.calcSignal(subAccount, tsCursor);

            // If signal exists then execute strategySignal
            if (signal)
            {
                RMarketEventLog::putRecord(subAccount.AccountId, subAccount.SubaccountId, 
                    RMarketLogLevel::Info, RMarketEventType::SignalDetected,
                    strFmt("%1: %2 #%3", dtCursor, enum2Str(strategySignal.Type), strategySignal.Num));

                this.executeAction(subAccount, strategySignal);
            }

            ttscommit;
        }
    }
}

protected void executeAction(RMarketSubAccount _subAccount, RMarketStrategySignal _signal)
{
    switch (_signal.type)
    {
        case RMarketSignalType::StopTrade:
            ttsbegin;
            _subAccount.Active = NoYes::No;
            _subAccount.update();
            ttscommit;
            RMarketEventLog::putRecord(_subAccount.AccountId, _subAccount.SubaccountId,
                RMarketLogLevel::Warning, RMarketEventType::StrategyDisabled,
                    strFmt("Trade is stopped!"));
            break;

        case RMarketSignalType::CloseLong:
            // Close long position by MarketOrder
            this.closePosition(_subAccount, RMarketPositionDirection::Long);
            break;
        case RMarketSignalType::CloseShort:
            // Close short position by MarketOrder
            this.closePosition(_subAccount, RMarketPositionDirection::Short);
            break;
        case RMarketSignalType::OpenLong:
            // Create new long position if long position not exists
            this.openPosition(_subAccount, RMarketPositionDirection::Long);
            break;
        case RMarketSignalType::OpenShort:
            // Create new short position if short position not exists
            this.openPosition(_subAccount, RMarketPositionDirection::Short);
            break;
        case RMarketSignalType::TrailOrder:
            // Not understand yet
        default:
            throw error(strFmt("Action type %1 isn't implemented yet!", enum2Str(_signal.type)));
    }
}

